"""Accessible, crawlable engine guide finder, built from the article records."""
import json,html,re
H=lambda v:html.escape(str(v),quote=True)
def build_directory(data):
 engines=data['engines']; rows=[]
 for e in engines:
  brands=e.get('application_brands') or [e['brand']]
  models=list(dict.fromkeys(a['vehicle'].split(' — ')[0] for a in e['applications']))
  rows.append(dict(code=e['code'],brands=brands,models=models,sa=any('south africa' in a['market'].lower() for a in e['applications']),url=e['code'].lower().replace('.','-')+'.html'))
 brands=sorted({b for r in rows for b in r['brands']})
 content='''<style>.finder-head h1{font-size:clamp(30px,4vw,46px);margin:10px 0}.finder-head .lead{font-size:17px;margin:10px 0 22px}.finder-form{padding:22px;background:#eeeee7;border:1px solid #d6d8cf;border-radius:8px}.finder-fields{display:grid;grid-template-columns:1fr 1fr 1.5fr;gap:18px}.finder-fields label{display:block;font-size:14px;font-weight:650}.finder-fields select,.finder-fields input{width:100%;min-width:0;margin-top:7px;padding:12px;background:white;border:1px solid #9caaa3;border-radius:4px;color:#23342c;font:16px system-ui;min-height:46px}.finder-tools{display:flex;justify-content:space-between;gap:15px;align-items:center;margin-top:16px;flex-wrap:wrap}.finder-tools label{font-size:14px}.finder-reset,.finder-more{font:600 15px system-ui;padding:12px 18px;min-height:44px;border:1px solid #5e7366;background:white;color:#244a35;border-radius:4px;cursor:pointer}.finder-reset:hover,.finder-more:hover{background:#e1e8df}.quick-brands{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0 24px}.quick-brands a{display:block;padding:8px 13px;border:1px solid #bbc5bc;border-radius:4px;min-height:44px;text-decoration:none;color:#284b36}.quick-brands a[aria-current=true]{background:#284b36;color:white;border-color:#284b36}.finder-results-head{display:flex;justify-content:space-between;align-items:baseline;gap:20px;margin:24px 0 12px}.finder-results-head h2{font-size:23px;margin:0}.finder-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 28px}.finder-result{display:grid;grid-template-columns:100px minmax(0,1fr) 22px;gap:18px;padding:21px 0;border-top:1px solid #d5d9d1;color:#20382b;text-decoration:none;align-items:start}.finder-result:hover{background:#f0f2ea}.finder-result b{font-size:21px;letter-spacing:-.02em;overflow-wrap:anywhere}.finder-result small{display:block;font-size:14px;color:#4c6053;line-height:1.6}.finder-result .models{margin-top:4px;font-size:15px;color:#2c3e34;line-height:1.6;overflow-wrap:anywhere}.finder-list .hidden{display:none}.finder-help{padding:20px 0;border-top:1px solid #cdd4ca;margin-top:28px;font-size:15px}.finder-help p{max-width:75ch}.finder-more{display:block;margin:22px auto}.finder-empty{padding:24px;background:#f0f2ea}.finder-empty[hidden]{display:none}.finder-note{font-size:14px;color:#4c6053;margin:12px 0}.finder-form select:focus-visible,.finder-form input:focus-visible,button:focus-visible{outline:3px solid #8c651f;outline-offset:3px}@media(max-width:700px){.wrap{padding:24px 20px 50px}.finder-fields{grid-template-columns:1fr 1fr;gap:12px}.finder-fields label:last-child{grid-column:1/-1}.finder-form{padding:16px}.finder-list{grid-template-columns:1fr}.finder-result{grid-template-columns:84px minmax(0,1fr) 16px;gap:12px}.finder-results-head{display:block}.quick-brands{gap:6px}.quick-brands a{font-size:14px}.nav{padding:16px 20px;gap:12px}.navlinks{gap:14px}.finder-head .lead{margin-bottom:18px}}</style><p class="crumb"><a href="/guides/">Blog &amp; buying guides</a> / Engine finder</p><header class="finder-head" style="background:transparent;border:0"><h1>Find the right engine guide.</h1><p class="lead">Choose your brand and model, or search the code stamped on your engine.</p></header><form class="finder-form" role="search" id="finder"><div class="finder-fields"><label for="brand-filter">1. Vehicle brand<select id="brand-filter" name="brand"><option value="">All brands</option>'''
 content+=''.join(f'<option>{H(b)}</option>' for b in brands)
 content+='''</select></label><label for="model-filter">2. Vehicle model<select id="model-filter" name="model"><option value="">All models</option></select></label><label for="engine-search">3. Engine code or keyword<input type="search" id="engine-search" name="q" placeholder="e.g. CSSA, A4L or 1AZ FE" autocomplete="off"></label></div><div class="finder-tools"><label><input id="market-filter" type="checkbox"> Include South Africa application records only</label><button type="button" class="finder-reset" id="reset-finder">Clear filters</button></div></form><nav class="quick-brands" aria-label="Popular engine brands">'''
 for b in ['Volkswagen','Audi','Mercedes-Benz','BMW','Toyota','Honda','Hyundai / Kia']:
  if b in brands:
   from urllib.parse import quote
   content+=f'<a href="?brand={quote(b)}" data-brand="{H(b)}">{H(b)}</a>'
 content+='''</nav><div class="finder-results-head"><h2 id="results-heading">Engine guides</h2><span id="match-count" role="status" aria-live="polite">'''+str(len(rows))+''' guides</span></div><p class="finder-note">Match the application year and full code inside each guide before ordering.</p><div class="finder-empty" id="empty" hidden><strong>No guide matches these filters.</strong><p>Try the full code without spaces, clear the model, or <a href="/contact.html">send your engine-code photo for help</a>.</p></div><div class="finder-list" id="engine-results">'''
 for r in sorted(rows,key=lambda r:r['code']):
  models=' · '.join(r['models'][:2]);models=models[:175]+'…' if len(models)>175 else models
  content+=f'<a class="finder-result tile-link" href="{r["url"]}" data-code="{H(r["code"])}"><b>{H(r["code"])}</b><span><small>{H(" / ".join(r["brands"]))}</small><span class="models">{H(models)}</span></span><span aria-hidden="true">↗</span></a>'
 content+='''</div><button type="button" id="load-more" class="finder-more" hidden>Show more guides</button><section class="finder-help"><h2>Not sure which code you need?</h2><p>Use the marking on the engine or your vehicle’s identification records. A model badge or an engine family such as EA888 is not enough to confirm the replacement.</p><a href="/contact.html">Get help identifying your engine →</a><details><summary>About application dates and availability</summary><p>Each article cites its application records. Shared codes do not prove that complete assemblies are interchangeable. Catalogue dates are not a guarantee of current production or available stock. Confirm the actual donor unit before ordering.</p></details></section>'''
 js='''<script>const records=__DATA__;const byCode=new Map(records.map(r=>[r.code,r]));const brand=document.getElementById('brand-filter'),model=document.getElementById('model-filter'),q=document.getElementById('engine-search'),market=document.getElementById('market-filter'),more=document.getElementById('load-more');let limit=24;const links=[...document.querySelectorAll('.finder-result')];const norm=s=>s.normalize('NFKC').toLowerCase().replace(/[\\s._\\-/]+/g,'');function modelOptions(value=''){const opts=[...new Set(records.filter(r=>!brand.value||r.brands.includes(brand.value)).flatMap(r=>r.models))].sort();model.replaceChildren(new Option('All models',''),...opts.map(m=>new Option(m,m)));model.value=opts.includes(value)?value:''}function apply(save=true){let count=0;const terms=q.value.trim().split(/\\s+/).filter(Boolean);for(const a of links){const r=byCode.get(a.dataset.code),hay=norm([r.code,...r.brands,...r.models].join(' '));const match=(!brand.value||r.brands.includes(brand.value))&&(!model.value||r.models.includes(model.value))&&(!market.checked||r.sa)&&(norm(r.code).includes(norm(q.value))||terms.every(t=>hay.includes(norm(t))));if(match)count++;const scoped=model.value?[model.value]:brand.value?r.models.filter(m=>m.toLowerCase().includes(brand.value.toLowerCase())):r.models;const names=(scoped.length?scoped:r.models).slice(0,2).join(' · ');a.querySelector('.models').textContent=names.length>175?names.slice(0,175)+'…':names;a.classList.toggle('hidden',!match||count>limit)}document.getElementById('match-count').textContent=count+' guides · '+Math.min(count,limit)+' shown';document.getElementById('results-heading').textContent=brand.value?brand.value+' engine guides':'Engine guides';document.getElementById('empty').hidden=count>0;more.hidden=count<=limit;document.querySelectorAll('[data-brand]').forEach(a=>a.setAttribute('aria-current',String(a.dataset.brand===brand.value)));if(save){const u=new URL(location.href);for(const key of ['brand','model','q','market'])u.searchParams.delete(key);if(brand.value)u.searchParams.set('brand',brand.value);if(model.value)u.searchParams.set('model',model.value);if(q.value.trim())u.searchParams.set('q',q.value.trim());if(market.checked)u.searchParams.set('market','south-africa');history.replaceState(null,'',u);try{sessionStorage.setItem('engineFinderReturn',u.pathname+u.search)}catch{}}}function readURL(){const u=new URL(location.href);brand.value=[...brand.options].some(o=>o.value===u.searchParams.get('brand'))?u.searchParams.get('brand'):'';q.value=u.searchParams.get('q')||'';market.checked=u.searchParams.get('market')==='south-africa';modelOptions(u.searchParams.get('model'));apply(false)}brand.addEventListener('change',()=>{limit=24;modelOptions();apply()});for(const el of [model,market])el.addEventListener('change',()=>{limit=24;apply()});q.addEventListener('input',()=>{limit=24;apply()});document.getElementById('finder').addEventListener('submit',e=>{e.preventDefault();apply();document.getElementById('results-heading').scrollIntoView({block:'start'})});document.getElementById('reset-finder').addEventListener('click',()=>{brand.value='';q.value='';market.checked=false;limit=24;modelOptions();apply()});document.querySelectorAll('[data-brand]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();brand.value=a.dataset.brand;limit=24;modelOptions();apply()}));more.addEventListener('click',()=>{const previous=limit;limit+=24;apply();const shown=links.filter(a=>!a.classList.contains('hidden'));shown[previous]?.focus()});links.forEach(a=>a.addEventListener('click',()=>{try{sessionStorage.setItem('engineFinderReturn',location.pathname+location.search);sessionStorage.setItem('engineFinderLimit',String(limit))}catch{}}));addEventListener('popstate',readURL);try{const n=Number(sessionStorage.getItem('engineFinderLimit'));if(n>24)limit=Math.min(n,records.length)}catch{}readURL();</script>'''.replace('__DATA__',json.dumps(rows,ensure_ascii=False).replace('</','<\\/'))
 return content,js
